Example program code
Python
def AddItem(Item):
global LinkedList
global StartEmptyList
global StartLinkedList
TempPosition = 0
if StartEmptyList != -1:
LinkedList[StartEmptyList][0] = Item
NewEmptyList = LinkedList[StartEmptyList][1]
LinkedList[StartEmptyList][1] = -1
TempPosition = StartLinkedList
while LinkedList[TempPosition][1] != -1:
     TempPosition = LinkedList[TempPosition][1]
LinkedList[TempPosition][1] = StartEmptyList
StartEmptyList = NewEmptyList
else:
print("List is full")
VB.NET
Sub AddItem(ByVal Item)
Dim TempPosition As Integer = 0
Dim NewEmptylist As Integer = 0
If StartEmptyList <> -1 Then
  LinkedList(StartEmptyList, 0) = Item
  NewEmptylist = LinkedList(StartEmptyList, 1)
  LinkedList(StartEmptyList, 1) = -1
  TempPosition = StartLinkedList
  While (LinkedList(TempPosition, 1) <> -1)
       TempPosition = LinkedList(TempPosition, 1)
  End While
  LinkedList(TempPosition, 1) = StartEmptyList
  StartEmptyList = NewEmptylist
Else
  Console.WriteLine("List is full")
End If
End Sub
Java
public static void AddItem(Integer Item){
Integer TempPosition = 0;
Integer NewEmptyList = 0;
if(StartEmptyList != -1){
    LinkedList[StartEmptyList][0] = Item;
    NewEmptyList = LinkedList[StartEmptyList][1];
    LinkedList[StartEmptyList][1] = -1;
    TempPosition = StartLinkedList;
    while(LinkedList[TempPosition][1] != -1){
          TempPosition = LinkedList[TempPosition][1];
    }
    LinkedList[TempPosition][1] = StartEmptyList;
    StartEmptyList = NewEmptyList;
}else{
    System.out.println("List is full");
}
}
